    (x1 t0 t1 t2 s1x a0 a1 a2 a3 a4 a5 a6 a7 s4x t3 t4 t5 t6 : word),
  AMI st stY -> c_init_done (ctx stY) = 1 -> s_regions stY = s_regions st -> c_avail_meta_area_count (ctx stY) = 0 ->
  0 <= c_meta_alloc_shift (ctx stY) <= 38 ->
